/* From Uiverse.io by Javierrocadev - Tags: list, blue, card, hover, dark, hover effect, card hover, mozilla */
.__UIV_SCOPE__ .card {
  width: 250px;
  height: 290px;
  border-radius: 15px;
  background: rgb(27, 26, 26);
  color: white;
  font-weight: 600;
  font-size: 1.2em;
  padding: 15px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-shadow: -5px 5px 1px 0px #004d92;
}

.__UIV_SCOPE__ .element {
  color: grey;
  font-size: .8em;
  padding: 6px 15px;
  border-left: 2px solid grey;
  cursor: pointer;
}

.__UIV_SCOPE__ .active {
  background-color: #004d92;
  border-left: 2px solid #8cb4ff;
  color: azure;
}

.__UIV_SCOPE__ .element:hover:not(.active) {
  color: #3775bb;
}
